SELECT
    wr.*,
    u.user_name,
    u.avatar,
    u.phone,
    wa.account_name,
    wa.account_number
FROM
    withdraw_record wr
LEFT JOIN tb_user u ON wr.user_id = u.user_id
LEFT JOIN withdrawal_account wa ON wr.user_id = wa.user_id AND wr.account_type = wa.type


        and wr.user_id = #{param.userId}


        and u.user_name = #{param.userName}


        and u.phone = #{param.phone}


        and wr.status = #{param.status}


        and wr.account_type = #{param.accountType}


        and sr.create_time between #{param.startTime} and #{param.endTime}


order by wr.create_time desc
